CREATE TABLE users(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, department text NOT NULL, role text NOT NULL CHECK(role IN ('buyer','approver','manager','supplier','accounting')));
CREATE TABLE suppliers(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, user_id integer UNIQUE REFERENCES users);
CREATE TABLE catalog_items(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, price integer NOT NULL CHECK(price>0), active boolean NOT NULL DEFAULT true);
CREATE TABLE purchase_requests(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, buyer_id integer NOT NULL REFERENCES users, department text NOT NULL, reason text NOT NULL, total integer NOT NULL CHECK(total>0), round integer NOT NULL DEFAULT 1 CHECK(round>0), status text NOT NULL CHECK(status IN ('pending','returned','rejected','approved','ordered','received','paid')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_request_items(request_id integer PRIMARY KEY REFERENCES purchase_requests, item_id integer NOT NULL REFERENCES catalog_items, quantity integer NOT NULL CHECK(quantity>0), price integer NOT NULL CHECK(price>0));
CREATE TABLE approval_steps(request_id integer REFERENCES purchase_requests, round integer CHECK(round>0), step integer CHECK(step IN (1,2)), role text NOT NULL CHECK(role IN ('approver','manager')), decision text CHECK(decision IN ('approve','return','reject')), actor_id integer REFERENCES users, comment text, acted_at timestamptz, PRIMARY KEY(request_id,round,step));
CREATE TABLE quotations(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id integer NOT NULL REFERENCES purchase_requests, supplier_id integer NOT NULL REFERENCES suppliers, amount integer NOT NULL CHECK(amount>0), quoted_at timestamptz NOT NULL DEFAULT now(), decision text CHECK(decision IN ('selected','declined')), selection_reason text, UNIQUE(request_id,supplier_id), UNIQUE(request_id,id,supplier_id));
CREATE UNIQUE INDEX one_selected ON quotations(request_id) WHERE decision='selected';
CREATE TABLE purchase_orders(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id integer NOT NULL UNIQUE REFERENCES purchase_requests, quote_id integer NOT NULL UNIQUE, supplier_id integer NOT NULL REFERENCES suppliers, amount integer NOT NULL CHECK(amount>0), quantity integer NOT NULL CHECK(quantity>0), buyer_id integer NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','confirmed','received','paid')), created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz, FOREIGN KEY(request_id,quote_id,supplier_id) REFERENCES quotations(request_id,id,supplier_id));
CREATE TABLE receipts(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id integer NOT NULL UNIQUE REFERENCES purchase_orders, actor_id integer NOT NULL REFERENCES users, quantity integer NOT NULL CHECK(quantity>=0), received_at timestamptz NOT NULL DEFAULT now(), result text NOT NULL CHECK(result IN ('complete','short')));
CREATE TABLE invoices(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id integer NOT NULL UNIQUE REFERENCES purchase_orders, amount integer NOT NULL CHECK(amount>0), invoice_date date NOT NULL, status text NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','paid')), paid_at timestamptz);
CREATE TABLE audit_logs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id integer NOT NULL REFERENCES purchase_requests, actor_id integer NOT NULL REFERENCES users, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_request ON audit_logs(request_id,id);
CREATE INDEX requests_status ON purchase_requests(status,created_at);
CREATE INDEX orders_supplier ON purchase_orders(supplier_id);
CREATE VIEW transactions AS
SELECT r.*, u.name AS buyer, c.name AS item, i.quantity, i.price, o.id AS order_id, o.amount AS order_amount, o.quantity AS order_quantity, o.status AS order_status, o.confirmed_at, s.name AS supplier, s.user_id AS supplier_user_id, x.quantity AS received_quantity,x.result AS receipt_result, f.id AS invoice_id,f.amount AS invoice_amount,f.status AS payment_status
FROM purchase_requests r JOIN users u ON u.id=r.buyer_id JOIN purchase_request_items i ON i.request_id=r.id JOIN catalog_items c ON c.id=i.item_id LEFT JOIN purchase_orders o ON o.request_id=r.id LEFT JOIN suppliers s ON s.id=o.supplier_id LEFT JOIN receipts x ON x.order_id=o.id LEFT JOIN invoices f ON f.order_id=o.id;